    /** True when estimateRowCount() returns the footer total the compute node reported rather than an estimate. */
    public boolean hasExactRowCount() {
        return footerRowCount > 0;
    }

    /**
     * Row count for the CBO. The footer total the compute node returned with the schema when present, else
     * HiveStatisticsProvider.getEstimatedRowCount's no-statistics rule (total bytes / sum of the file columns'
     * type widths), else 1. Each width is floored at 1 so a zero-width type cannot zero the denominator (the one
     * deviation from the Hive rule). LIST_FILES tables answer one row per directory entry from their own schema
     * and keep 1; UNLOAD tables list no files and keep 1. Config.files_scan_estimate_row_count = false restores
     * upstream's 1 row for every FILES() scan.
     */
    public long estimateRowCount() {
        if (!Config.files_scan_estimate_row_count || listFilesOnly || fileStatuses.isEmpty()) {
            return 1;
        }
        if (footerRowCount > 0) {
            return footerRowCount;
        }
        long bytes = getTotalFileBytes();
        long width = 0;
        for (Column c : getFileColumns()) {
            width += Math.max(1, c.getType().getTypeSize());
        }
        if (bytes <= 0 || width <= 0) {
            return 1;
        }
        return Math.max(1L, bytes / width);
    }

